#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
ENV_FILE="${ENV_FILE:-$REPO_ROOT/ide/.publish.env}"
VSIX="$REPO_ROOT/ide/vscode/build-ai-context-0.1.0.vsix"
ZIP="$REPO_ROOT/ide/intellij/plugin/build/distributions/plugin-0.1.0.zip"
SCREENSHOT="$REPO_ROOT/docs/ide-plugins/media/marketplace-1200x760.png"

TOTAL_STAGES=8

banner "Publish Build AI Context Hosts"

# ── Stage 1 ──────────────────────────────────────────────────────────────
stage "Confirm local packages"
say "This wizard does not build. It walks the marketplace accounts, agreements, and uploads."
say "Packages this run expects:"
note "VSIX  $VSIX"
note "ZIP   $ZIP"
note "Shot  $SCREENSHOT"
if [[ ! -f $VSIX || ! -f $ZIP ]]; then
  warn "A package is missing. Build first, then re-run this wizard:"
  note "npm --prefix ide/vscode test && npm --prefix ide/vscode run package"
  note "(cd ide/intellij && ./gradlew :engine:test :plugin:buildPlugin --no-daemon)"
  pause "Build those packages, then press Enter (or Ctrl-C to stop)."
fi
[[ -f $VSIX && -f $ZIP ]] || { warn "Still missing packages; stop and rebuild."; exit 1; }
step "Open the listing copy if you want a last read: ide/vscode/README.md and ide/intellij/plugin/README.md."
pause "Packages are present. Continue?"

# ── Stage 2 ──────────────────────────────────────────────────────────────
stage "Visual Studio Marketplace publisher"
say "Publisher ID asjnaang is permanent. It must match ide/vscode/package.json."
open_url "https://go.microsoft.com/fwlink/?LinkId=307137"
step "Sign in with the Microsoft account that will own the publisher (create an Azure DevOps org if asked)."
open_url "https://marketplace.visualstudio.com/manage"
step "Create publisher if it does not exist. ID: asjnaang  Display name: ASJN. The ID cannot be changed later."
pause "Publisher asjnaang exists?"

# ── Stage 3 ──────────────────────────────────────────────────────────────
stage "Upload the VS Code VSIX"
say "Web upload is enough for the first release. A PAT is only needed for vsce later."
open_url "https://marketplace.visualstudio.com/manage"
step "New extension → Visual Studio Code → upload:"
note "$VSIX"
step "Confirm MIT license, repository https://github.com/asjnaang/Build-AI-Context, and the README screenshot."
step "Publish. Malware scan runs before the listing goes live."
open_url "https://marketplace.visualstudio.com/items?itemName=asjnaang.build-ai-context"
pause "Marketplace item asjnaang.build-ai-context is up (or submitted)?"

# ── Stage 4 ──────────────────────────────────────────────────────────────
stage "Open VSX publisher agreement"
say "Open VSX is for Cursor / VSCodium. Use the same id: publisher asjnaang, name build-ai-context."
open_url "https://accounts.eclipse.org/user/register"
step "Create or sign in to an Eclipse account. Set GitHub Username to the same GitHub account you will use on Open VSX."
open_url "https://open-vsx.org"
step "Log in with GitHub."
open_url "https://open-vsx.org/user-settings/profile"
step "Log in with Eclipse → Show Publisher Agreement → Agree. Eclipse ECA is a different agreement; skip it unless you contribute to Eclipse projects."
pause "Open VSX Publisher Agreement accepted?"

# ── Stage 5 ──────────────────────────────────────────────────────────────
stage "Publish the same VSIX to Open VSX"
open_url "https://open-vsx.org/user-settings/tokens"
step "Generate New Token, copy it once, and paste it here. It is stored in ide/.publish.env (gitignored)."
ask_secret OVSX_PAT "Paste the Open VSX token:"
write_env OVSX_PAT "$OVSX_PAT"
say "Create the namespace if it does not exist, then publish."
note "npx ovsx create-namespace asjnaang -p \"\$OVSX_PAT\""
note "npx ovsx publish \"$VSIX\" -p \"\$OVSX_PAT\""
if confirm "Run those two commands from this wizard now?"; then
  npx --yes ovsx create-namespace asjnaang -p "$OVSX_PAT" || warn "create-namespace failed (namespace may already exist)."
  npx --yes ovsx publish "$VSIX" -p "$OVSX_PAT"
fi
if confirm "Also store OVSX_PAT as a GitHub Actions secret for later CI?"; then
  set_secret OVSX_PAT "$OVSX_PAT"
fi
open_url "https://open-vsx.org/extension/asjnaang/build-ai-context"
pause "Open VSX listing asjnaang.build-ai-context is up, or you skipped CLI publish?"

# ── Stage 6 ──────────────────────────────────────────────────────────────
stage "JetBrains vendor (irreversible ID)"
say "The first JetBrains upload must be manual. Vendor ID cannot be edited later."
open_url "https://account.jetbrains.com"
step "Sign in or create a JetBrains Account."
open_url "https://plugins.jetbrains.com/organizations/new"
step "Create the vendor if needed. Recommended Vendor ID: asjnaang  Public name: ASJN."
warn "Choose the Vendor ID carefully; you will not be able to edit it."
step "Declare trader or non-trader (EU consumer rules). Accept the Marketplace Developer Agreement."
ask SUPPORT_EMAIL "Public support email for the listing:"
write_env SUPPORT_EMAIL "$SUPPORT_EMAIL"
ask VENDOR_WEBSITE "Vendor website [Enter keeps GitHub repo]:"
[[ -z ${VENDOR_WEBSITE:-} ]] && VENDOR_WEBSITE="https://github.com/asjnaang/Build-AI-Context"
write_env VENDOR_WEBSITE "$VENDOR_WEBSITE"
pause "Vendor profile and agreements are done?"

# ── Stage 7 ──────────────────────────────────────────────────────────────
stage "Upload the IntelliJ / Android Studio zip"
open_url "https://plugins.jetbrains.com/plugin/add#intellij"
step "Upload plugin → select:"
note "$ZIP"
step "Plugin XML id is already com.asjnaang.buildaicontext. License: MIT. Source: https://github.com/asjnaang/Build-AI-Context"
step "Support email: the value just saved. Website: $VENDOR_WEBSITE"
step "Leave the release channel empty for Stable. Add a tag such as AI / Export."
step "Media: upload this 1200×760 screenshot:"
note "$SCREENSHOT"
step "Submit for review. JetBrains reviews every new plugin; if there is no word in 3–4 working days, email marketplace@jetbrains.com."
pause "Zip uploaded and submitted?"

# ── Stage 8 ──────────────────────────────────────────────────────────────
stage "Optional tokens for later updates"
say "Skip this stage if you will keep using the web UIs."
if confirm "Create a Visual Studio Marketplace PAT (Marketplace → Manage) and save it?"; then
  open_url "https://dev.azure.com"
  step "User settings → Personal access tokens → New Token. Organization: All accessible organizations. Scope: Marketplace → Manage."
  warn "Global Azure DevOps PATs retire 1 December 2026; prefer Entra/workload identity after that."
  ask_secret VSCE_PAT "Paste the Marketplace PAT:"
  write_env VSCE_PAT "$VSCE_PAT"
  if confirm "Store VSCE_PAT as a GitHub Actions secret?"; then
    set_secret VSCE_PAT "$VSCE_PAT"
  fi
fi
if confirm "Create a JetBrains Marketplace token for later Gradle publishPlugin?"; then
  open_url "https://plugins.jetbrains.com/author/me/tokens"
  step "Generate Token, copy it once. Gradle reads PUBLISH_TOKEN."
  ask_secret PUBLISH_TOKEN "Paste the JetBrains Marketplace token:"
  write_env PUBLISH_TOKEN "$PUBLISH_TOKEN"
  if confirm "Store PUBLISH_TOKEN as a GitHub Actions secret?"; then
    set_secret PUBLISH_TOKEN "$PUBLISH_TOKEN"
  fi
fi
say "After both listings are live, replace preview language in README.md with the public URLs."
pause "Tokens done or skipped?"

finish
}

run_wizard "$@"; exit
